import { path } from '@servicenow/sdk-build-core'
import { createTestContext, findInput, getMergedRecordUpdates, loadTestFile, unzipInputArray } from '../test-utils'
import { gunzipSync } from 'zlib'

describe('ForEach Bi-Directionality Test Suite', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('ForEach - Fluent to XML', () => {
        test('ForEach with simple data pill', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'foreach-simple.now.ts', // Your test file for ForEach
                'flow-logics/fluent'
            )

            // Verify flow logic instance was created
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            expect(flowLogicInstances.length).toBeGreaterThan(0)

            // Get the first ForEach instance
            const forEachInstance = flowLogicInstances[0]
            expect(forEachInstance).toBeDefined()

            // Verify items field
            const valuesJson = JSON.parse(gunzipSync(Buffer.from(forEachInstance.values, 'base64')).toString('utf8'))
            expect(valuesJson.inputs).toBeDefined()
            expect(valuesJson.inputs.length).toBeGreaterThan(0)

            // Find the items input
            const itemsInput = valuesJson.inputs.find(
                (input: { name: string; value: string; displayValue: string }) => input.name === 'items'
            )
            expect(itemsInput).toBeDefined()
            expect(itemsInput.value).toBe('{{Created_1.current.watch_list}}')
            expect(itemsInput.displayValue).toBe('{{Created_1.current.watch_list}}')
        })

        test('ForEach with nested structure', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'foreach-nested.now.ts', // Your test file for nested ForEach
                'flow-logics/fluent'
            )

            // Verify nested flow logic instances
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            expect(flowLogicInstances.length).toBeGreaterThan(1) // Ensure we have multiple instances

            // Verify structure of nested ForEach
            const outerForEach = flowLogicInstances.find(
                (instance) => instance['logic_definition'] === '098e1dc5c3e232002841b63b12d3ae33'
            )
            expect(outerForEach).toBeDefined()
            // Further checks for nested structure...
        })
    })

    describe('ForEach - XML to Fluent', () => {
        test('ForEach with simple data pill transforms correctly', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('sys_hub_flow_773e7641c4f93610f877ba0833e698e4.xml', 'flow-logics/xmls')
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_773e7641c4f93610f877ba0833e698e4.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            expect(changedFiles[0].getName()).toBe('sys_hub_flow_773e7641c4f93610f877ba0833e698e4.now.ts')

            const content = changedFiles[0].getContent()

            // Verify ForEach structure exists
            expect(content).toContain('wfa.flowLogic.forEach(')

            // Verify data pill in ForEach items is converted correctly
            expect(content).toContain('.trigger.current.additional_assignee_list')

            // Verify action inside ForEach
            expect(content).toContain('action.core.log')
        })

        test('Nested ForEach structure transforms correctly', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('sys_hub_flow_debe8741c47d3610f877ba0833e6980c.xml', 'flow-logics/xmls')
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_debe8741c47d3610f877ba0833e6980c.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            expect(changedFiles[0].getName()).toBe('sys_hub_flow_debe8741c47d3610f877ba0833e6980c.now.ts')

            const content = changedFiles[0].getContent()

            // Verify multiple ForEach calls exist (nested structure)
            const firstForEach = content.indexOf('wfa.flowLogic.forEach(')
            const secondForEach = content.indexOf('wfa.flowLogic.forEach(', firstForEach + 1)
            expect(firstForEach).toBeGreaterThan(-1)
            expect(secondForEach).toBeGreaterThan(-1)

            // Verify outer ForEach uses trigger data pill
            expect(content).toContain('.trigger.current.')

            // Verify action inside nested ForEach
            expect(content).toContain('action.core.log')
        })

        // ========================================================================
        // Test: ForEach with no data pill assigned (edge case)
        // ========================================================================
        // Purpose: Test transformation of a forEach that has no data pill assigned
        //          This validates the fix for StringLiteralShape -> PropertyAccessShape casting error
        // ========================================================================
        test('ForEach with no data pill (empty string) transforms successfully', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('DEF0790630.xml', 'flow-logics/xmls')

            const { changedFiles } = await project.transform({
                path: 'DEF0790630.xml',
                content: xmlContent,
            })

            expect(changedFiles.length).toBeGreaterThan(0)
            const content = changedFiles[0].getContent()

            // Verify Flow structure
            expect(content).toContain('Flow(')
            expect(content).toContain("name: 'Example_1_Daily Incident Processor'")

            // Verify forEach exists
            expect(content).toContain('wfa.flowLogic.forEach(')

            // Verify forEach with no data pill assigned generates empty string
            // This validates the fix for StringLiteralShape -> PropertyAccessShape casting error
            // The code is formatted with line breaks, so check for the pattern
            expect(content).toContain('wfa.flowLogic.forEach(')
            expect(content).toContain("'',")

            // Verify other flow elements to ensure transformation succeeded
            expect(content).toContain('trigger.record.created')
            expect(content).toContain('action.core.log')
        })
    })

    describe('ForEach Data Pill UUID Prefix Tests', () => {
        test('Simple forEach: data pills get UUID prefix', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'foreach-datapill-simple.now.ts',
                'flow-logics/fluent'
            )

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            const forEachLoop = flowLogicInstances.find((instance: any) => instance.ui_id && !instance.parent_ui_id)
            expect(forEachLoop).toBeDefined()
            const forEachUUID = forEachLoop.ui_id

            const actionInstances = merged['sys_hub_action_instance_v2']
            const logAction = actionInstances.find((a: any) => a.parent_ui_id === forEachUUID)
            expect(logAction).toBeDefined()

            const inputs = unzipInputArray(logAction.values)
            const logMessage = findInput(inputs, 'log_message')

            // Verify data pills have UUID prefix
            expect(logMessage.value).toContain(`{{${forEachUUID}.item.number}}`)
            expect(logMessage.value).toContain(`{{${forEachUUID}.item.assignment_group}}`)
            // Verify NO unprefixed data pills
            expect(logMessage.value).not.toContain('{{forEach.item.number}}')
            expect(logMessage.value).not.toContain('{{forEach.item.assignment_group}}')
        })

        test('Nested forEach: each loop gets distinct UUID prefix', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'foreach-datapill-nested.now.ts',
                'flow-logics/fluent'
            )

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Find outer forEach (no parent)
            const outerForEach = flowLogicInstances.find((instance: any) => instance.ui_id && !instance.parent_ui_id)
            expect(outerForEach).toBeDefined()
            const outerUUID = outerForEach.ui_id

            // Find inner forEach (has parent_ui_id)
            const innerForEach = flowLogicInstances.find((instance: any) => instance.parent_ui_id === outerUUID)
            expect(innerForEach).toBeDefined()
            const innerUUID = innerForEach.ui_id

            // Verify UUIDs are different
            expect(outerUUID).not.toEqual(innerUUID)

            const actionInstances = merged['sys_hub_action_instance_v2']

            // Find inner action (references both loops)
            const innerAction = actionInstances.find((a: any) => a.parent_ui_id === innerUUID)
            expect(innerAction).toBeDefined()

            const inputs = unzipInputArray(innerAction.values)
            const logMessage = findInput(inputs, 'log_message')

            // Verify outer loop item uses outer UUID
            expect(logMessage.value).toContain(`{{${outerUUID}.item.number}}`)
            // Verify inner loop item uses inner UUID
            expect(logMessage.value).toContain(`{{${innerUUID}.item.number}}`)
            // Verify NO unprefixed data pills
            expect(logMessage.value).not.toContain('{{forEach.item.number}}')
        })
    })
})
